// Command eci-presets generates ECI agent definitions from role templates and model profiles.
//
// From the repository root, run:
//
//	(cd agent/eci/tools/eci-presets && go run . -config ../../model-selection.yaml -templates templates -out ../../../agents)
//
// Add --check to report drift without writing.
package main

import (
	"bytes"
	"crypto/rand"
	"crypto/sha256"
	"errors"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"text/template"

	"gopkg.in/yaml.v3"
)

const (
	// outputPrefix reserves generated filenames without claiming other user agents.
	//
	// Example: eci-preset-explorer-openai-default.md.
	outputPrefix = "eci-preset-"
	// generatedMarker identifies legacy output eligible only for exact-content migration.
	//
	// Example: an obsolete legacy file is never deleted.
	generatedMarker = "<!-- Generated by eci-presets; do not edit. -->"
	// digestPrefix identifies a self-verifying generated file.
	//
	// Example: the marker carries the SHA-256 of all preceding bytes.
	digestPrefix = "<!-- Generated by eci-presets; sha256:"
)

// profile contains one configured model and its reasoning effort.
//
// Example: an openai default profile has a model and medium effort.
type profile struct {
	Model  string `yaml:"model"`
	Effort string `yaml:"reasoning_effort"`
}

// profileLevel orders activity profiles from routine to most demanding.
//
// Example: a mixed assignment uses its highest applicable profile.
type profileLevel int

const (
	// defaultLevel is the profile for routine work.
	//
	// Example: implementation uses the default profile.
	defaultLevel profileLevel = iota
	// higherLevel is the profile for independent review.
	//
	// Example: Critic A uses the higher profile.
	higherLevel
	// maxLevel is the profile for design or long-term review.
	//
	// Example: Step 2 uses the max profile.
	maxLevel
)

// roleProfile identifies an ECI role and its minimum applicable profile.
//
// Example: a design critic starts at max.
type roleProfile struct {
	Name    string
	Minimum profileLevel
}

// templateData supplies the role-specific fields for one generated agent.
//
// Example: Name identifies a reviewer with its camp and activity profile.
type templateData struct {
	Name     string
	Primary  string
	Fallback string
}

// generate renders every role and profile from the supplied authoritative files.
//
// Example: a Step 2 critic has only max variants for both camps.
func generate(
	configPath string,
	templateDir string,
) (map[string][]byte, error) {
	data, err := os.ReadFile(configPath)
	if err != nil {
		return nil, err
	}
	var profiles map[string]map[string]profile
	decoder := yaml.NewDecoder(bytes.NewReader(data))
	decoder.KnownFields(true)
	if err := decoder.Decode(&profiles); err != nil {
		return nil, err
	}
	camps := []string{"anthropic", "openai"}
	levels := []string{"default", "higher", "max"}
	// Floors follow the activity table in the ECI skill; mixed work can only raise them.
	roles := []roleProfile{
		{Name: "explorer", Minimum: defaultLevel},
		{Name: "critic-step2", Minimum: maxLevel},
		{Name: "implementer", Minimum: defaultLevel},
		{Name: "fast-owner", Minimum: defaultLevel},
		{Name: "reviewer", Minimum: higherLevel},
		{Name: "independent-e2e", Minimum: higherLevel},
		{Name: "orchestrator", Minimum: defaultLevel},
		{Name: "helper", Minimum: defaultLevel},
	}
	if len(profiles) != len(camps) {
		return nil, errors.New("model selection must contain exactly two camps")
	}
	for _, camp := range camps {
		if len(profiles[camp]) != len(levels) {
			return nil, fmt.Errorf("camp %s must contain exactly three profiles", camp)
		}
		for _, level := range levels {
			p, ok := profiles[camp][level]
			if !ok || p.Model == "" || p.Effort == "" || strings.ContainsAny(p.Model+p.Effort, "\r\n\" ") {
				return nil, fmt.Errorf("invalid %s/%s selector", camp, level)
			}
		}
	}
	base, err := os.ReadFile(filepath.Join(templateDir, "task-base.tmpl"))
	if err != nil {
		return nil, err
	}
	baseText := strings.TrimRight(string(base), "\n")
	result := make(map[string][]byte, len(roles)*len(camps)*len(levels))
	for _, role := range roles {
		body, err := os.ReadFile(filepath.Join(templateDir, role.Name+".tmpl"))
		if err != nil {
			return nil, err
		}
		tmpl, err := template.New(role.Name).Option("missingkey=error").Parse(string(body))
		if err != nil {
			return nil, err
		}
		for _, camp := range camps {
			other := "openai"
			if camp == "openai" {
				other = "anthropic"
			}
			for index, level := range levels {
				if profileLevel(index) < role.Minimum {
					continue
				}
				primary, fallback := profiles[camp][level], profiles[other][level]
				name := outputPrefix + role.Name + "-" + camp + "-" + level
				args := templateData{Name: name, Primary: primary.Model + ":" + primary.Effort, Fallback: fallback.Model + ":" + fallback.Effort}
				var rendered bytes.Buffer
				if err := tmpl.Execute(&rendered, args); err != nil {
					return nil, err
				}
				content := strings.TrimRight(rendered.String(), "\n") + "\n\n" + baseText + "\n\n"
				result[name+".md"] = stamp([]byte(content))
			}
		}
	}
	return result, nil
}

// stamp appends an ownership digest to the complete generated content.
//
// Example: stamp([]byte("body\n")) records the hash of that body.
func stamp(content []byte) []byte {
	sum := sha256.Sum256(content)
	return append(bytes.Clone(content), []byte(fmt.Sprintf("%s%x -->\n", digestPrefix, sum))...)
}

// reconcile checks or updates only files belonging to this generator.
//
// Example: check reports missing, stale and obsolete definitions without mutation.
func reconcile(
	dir string,
	want map[string][]byte,
	check bool,
) error {
	entries, err := os.ReadDir(dir)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	var issues, conflicts, obsolete []string
	existing := make(map[string][]byte)
	for _, entry := range entries {
		name := entry.Name()
		if !strings.HasPrefix(name, outputPrefix) || !strings.HasSuffix(name, ".md") {
			continue
		}
		info, err := entry.Info()
		if err != nil {
			return fmt.Errorf("inspect %s: %w", name, err)
		}
		if !info.Mode().IsRegular() {
			conflicts = append(conflicts, "not a regular file: "+name)
			continue
		}
		data, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil {
			return fmt.Errorf("read %s: %w", name, err)
		}
		expected, needed := want[name]
		marker := bytes.LastIndex(data, []byte(digestPrefix))
		valid := marker >= 0 && bytes.Equal(stamp(data[:marker]), data)
		if !valid && needed {
			expectedMarker := bytes.LastIndex(expected, []byte(digestPrefix))
			if expectedMarker >= 0 {
				legacy := append(bytes.Clone(expected[:expectedMarker]), []byte(generatedMarker+"\n")...)
				valid = bytes.Equal(data, legacy)
			}
		}
		if !valid {
			conflicts = append(conflicts, "unowned or modified: "+name)
			continue
		}
		existing[name] = data
		if !needed {
			issues = append(issues, "obsolete: "+name)
			obsolete = append(obsolete, name)
		}
	}
	var names []string
	for name := range want {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		data, ok := existing[name]
		switch {
		case !ok:
			issues = append(issues, "missing: "+name)
		case !bytes.Equal(data, want[name]):
			issues = append(issues, "stale: "+name)
		}
	}
	if len(conflicts) != 0 {
		sort.Strings(conflicts)
		return errors.New(strings.Join(conflicts, "\n"))
	}
	if check {
		if len(issues) != 0 {
			sort.Strings(issues)
			return errors.New(strings.Join(issues, "\n"))
		}
		return nil
	}
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	for _, name := range names {
		if bytes.Equal(existing[name], want[name]) {
			continue
		}
		if err := publishFile(filepath.Join(dir, name), existing[name], want[name]); err != nil {
			return fmt.Errorf("write %s: %w", name, err)
		}
	}
	for _, name := range obsolete {
		if err := removeUnchanged(filepath.Join(dir, name), existing[name]); err != nil {
			return fmt.Errorf("remove %s: %w", name, err)
		}
	}
	return nil
}

// unchangedMode checks that a regular target still has its preflight content.
//
// Example: an intervening user edit is reported instead of overwritten.
func unchangedMode(
	path string,
	expected []byte,
) (os.FileMode, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return 0, err
	}
	if !info.Mode().IsRegular() {
		return 0, fmt.Errorf("target is not a regular file: %s", path)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	if !bytes.Equal(data, expected) {
		return 0, fmt.Errorf("target changed since preflight: %s", path)
	}
	return info.Mode().Perm(), nil
}

// publishFile stages a complete file before replacing an unchanged target.
//
// Example: a newly created target is linked without replacing another file.
func publishFile(
	path string,
	expected []byte,
	content []byte,
) (_err error) {
	mode := os.FileMode(0644)
	if expected != nil {
		var err error
		mode, err = unchangedMode(path, expected)
		if err != nil {
			return err
		}
	}
	var nonce [16]byte
	if _, err := rand.Read(nonce[:]); err != nil {
		return err
	}
	tempPath := filepath.Join(filepath.Dir(path), fmt.Sprintf(".eci-preset-%x", nonce))
	temp, err := os.OpenFile(tempPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0644)
	if err != nil {
		return err
	}
	closed := false
	defer func() {
		if !closed {
			_err = errors.Join(_err, temp.Close())
		}
		if err := os.Remove(temp.Name()); err != nil && !errors.Is(err, os.ErrNotExist) {
			_err = errors.Join(_err, err)
		}
	}()
	if _, err := temp.Write(content); err != nil {
		return err
	}
	if expected != nil {
		if err := temp.Chmod(mode); err != nil {
			return err
		}
	}
	if err := temp.Sync(); err != nil {
		return err
	}
	if err := temp.Close(); err != nil {
		closed = true
		return err
	}
	closed = true
	if expected == nil {
		return os.Link(temp.Name(), path)
	}
	currentMode, err := unchangedMode(path, expected)
	if err != nil {
		return err
	}
	if currentMode != mode {
		return fmt.Errorf("target mode changed since preflight: %s", path)
	}
	return os.Rename(temp.Name(), path)
}

// removeUnchanged removes an obsolete file only after rechecking its content.
//
// Example: a modified obsolete file is left for its owner.
func removeUnchanged(
	path string,
	expected []byte,
) error {
	if _, err := unchangedMode(path, expected); err != nil {
		return err
	}
	return os.Remove(path)
}

// main reads explicit paths and either generates or checks the user agent directory.
//
// Example: eci-presets -config profiles.yaml -templates templates -out agents --check.
func main() {
	config := flag.String("config", "", "model-selection.yaml path")
	templates := flag.String("templates", "", "role template directory")
	out := flag.String("out", "", "user agent directory")
	check := flag.Bool("check", false, "report differences without writing")
	flag.Parse()
	if *config == "" || *templates == "" || *out == "" || flag.NArg() != 0 {
		fmt.Fprintln(os.Stderr, "-config, -templates and -out are required")
		os.Exit(2)
	}
	want, err := generate(*config, *templates)
	if err == nil {
		err = reconcile(*out, want, *check)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
